insert into public.testimonials (name, role, quote, sort_order, status)
values
  ('Hetal Patel', 'Homeowner, Chandkheda', 'We saw three projects in two days and never felt rushed. They explained paperwork in Gujarati when my parents asked, which made our whole family comfortable.', 1, 'active'),
  ('Nirav Shah', 'Investor, Gota', 'I was looking for a 3 BHK near SG Highway. Every option came with possession dates and RERA numbers up front. No chasing, no vague answers.', 2, 'active'),
  ('Mansi Desai', 'Homeowner, Bopal', 'Site visits were organised around our office timings. They waited with us at a sample flat and compared two floor plans without pushing either one.', 3, 'active'),
  ('Karan Mehta', 'Homeowner, Science City', 'This was our first home. Pricing, extras, and what a builder would actually deliver were written down before we signed. That honesty is rare here.', 4, 'active'),
  ('Ruchi Trivedi', 'Investor, Motera', 'Needed a 2 BHK for rental near Motera stadium. They filtered by yield and possession, not glossy brochures. We closed on a ready unit in three weeks.', 5, 'active'),
  ('Jignesh Panchal', 'Homeowner, Vaishnodevi Circle', 'We came from Paldi looking west-side. They knew which towers get evening sun and which stay noisy beside SG Highway. That detail saved us a wrong booking.', 6, 'active'),
  ('Priya Joshi', 'Homeowner, Shela', 'We were stuck between Shela and Bopal. One afternoon they walked us through both, then left us to decide. We closed next week with no follow-up pressure.', 7, 'active'),
  ('Amit Vyas', 'Investor, Kudasan', 'GIFT City commute was our brief. They showed three ready options in Kudasan and Raysan with actual travel times, not marketing maps.', 8, 'active'),
  ('Sneha Raval', 'Homeowner, Tragad', 'Parents wanted to stay close to family in Chandkheda. They found a ready 3 BHK we could move into that same month, with amenities we actually use.', 9, 'active'),
  ('Harshad Solanki', 'Homeowner, New CG Road', 'We had a budget and a possession deadline. They did not show us anything outside either. Closed in three visits, all on Sunday mornings.', 10, 'active');
